// ─────────────────────────────────────────────────────────────────────
// La tira «NUESTROS PROYECTOS Y PRODUCTOS» del pie de la cotización.
//
// Sale del Excel manual: es UNA sola imagen ancha —no nueve fotos sueltas—
// que la planilla estira de lado a lado bajo los términos. Se extrajo de
// xl/media/image1.png de «JEFERSON- LA FLORIDA.xlsm» (2646 × 284 px, 1,8 MB),
// se redujo a 1400 × 150 y se guardó en JPEG: son fotos sin transparencia, así
// que acá el JPEG pesa una fracción del PNG (48 KB contra 1,8 MB) y a 194 mm de
// ancho no se nota. Los sellos, en cambio, SÍ tienen que ser PNG: van sobre
// fondos de color y necesitan el canal alfa.
//
// Vive en su propio módulo para que entre al chunk 'pdf', que se carga solo
// cuando alguien descarga el documento.
// ─────────────────────────────────────────────────────────────────────

/** Tira de fotos de proyectos, 1400 × 150 px. */
export const TIRA_PROYECTOS = 'data:image/jpeg;base64,';

/** Ancho ÷ alto de la tira, para no deformarla al dibujarla. */
export const TIRA_PROYECTOS_RATIO = 1400 / 150;
